namespace UI_Desktop.Store;

internal static class StorefrontHomeHtmlBuilder
{
	private const int CatalogBatchSize = 20;

	internal static string BuildDocument(StorePageData pageData, IReadOnlyList<StoreGame> spotlightGames, IReadOnlyList<StoreCategorySection> categorySections, IReadOnlyList<StoreGame> filteredGames, int activeSpotlightIndex)
	{
		IReadOnlyList<StoreGame> readOnlyList2;
		if (spotlightGames.Count <= 0)
		{
			IReadOnlyList<StoreGame> readOnlyList = ((filteredGames.Count > 0) ? filteredGames.Take(6).ToArray() : pageData.Games.Take(6).ToArray());
			readOnlyList2 = readOnlyList;
		}
		else
		{
			readOnlyList2 = spotlightGames;
		}
		IReadOnlyList<StoreGame> readOnlyList3 = readOnlyList2;
		IReadOnlyList<StoreCategorySection> readOnlyList5;
		if (categorySections.Count <= 0)
		{
			IReadOnlyList<StoreCategorySection> readOnlyList4 = new _003C_003Ez__ReadOnlySingleElementList<StoreCategorySection>(new StoreCategorySection
			{
				Name = "Tất cả game",
				Slug = "tat-ca-game",
				Games = ((filteredGames.Count > 0) ? filteredGames : pageData.Games)
			});
			readOnlyList5 = readOnlyList4;
		}
		else
		{
			readOnlyList5 = categorySections;
		}
		IReadOnlyList<StoreCategorySection> source = readOnlyList5;
		HashSet<Guid> visibleGameIds = (from game in source.SelectMany((StoreCategorySection section) => section.Games)
			select game.GameId).ToHashSet();
		StoreSaleGame[] source2 = pageData.SaleGames.Where((StoreSaleGame sale) => visibleGameIds.Count == 0 || visibleGameIds.Contains(sale.GameId)).ToArray();
		var model = new
		{
			activeSpotlightIndex = ((readOnlyList3.Count != 0) ? Math.Clamp(activeSpotlightIndex, 0, readOnlyList3.Count - 1) : 0),
			catalogBatchSize = 20,
			spotlightGames = readOnlyList3.Select(CreateSpotlightPayload).ToArray(),
			saleGames = source2.Select(CreateSalePayload).ToArray(),
			categorySections = source.Select(CreateCategorySectionPayload).ToArray(),
			games = filteredGames.Select(CreateCatalogPayload).ToArray()
		};
		return $"<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n<head>\r\n<meta charset=\"utf-8\" />\r\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\r\n<title>{WebUtility.HtmlEncode(pageData.LauncherName)} Storefront</title>\r\n<style>\r\n{BuildStyles()}\r\n</style>\r\n</head>\r\n<body>\r\n<div class=\"storefront-shell\">\r\n    <section class=\"spotlight-host\" data-spotlight-host></section>\r\n    <section class=\"sale-shell\" data-sale-shell hidden>\r\n        <div class=\"catalog-header\">\r\n            <div>\r\n                <h2 class=\"catalog-title\">Game đang sale</h2>\r\n            </div>\r\n        </div>\r\n        <div class=\"sale-grid\" data-sale-grid></div>\r\n    </section>\r\n    <section class=\"catalog-shell\">\r\n        <div class=\"catalog-header\">\r\n            <div>\r\n                <h2 class=\"catalog-title\">Khám phá</h2>\r\n            </div>\r\n            <div class=\"catalog-counter\" data-catalog-counter></div>\r\n        </div>\r\n        <div class=\"catalog-empty\" data-empty-state hidden>\r\n            <div class=\"catalog-empty-icon\">?</div>\r\n            <h3>Không tìm thấy sản phẩm</h3>\r\n            <p>Điều chỉnh từ khóa hoặc bộ lọc để xem thêm trò chơi phù hợp.</p>\r\n        </div>\r\n        <div class=\"catalog-sections\" data-catalog-sections></div>\r\n        <div class=\"catalog-loader\" data-catalog-loader hidden>\r\n            <span class=\"catalog-loader-spinner\" aria-hidden=\"true\"></span>\r\n            <span data-catalog-loader-text>Đang tải thêm trò chơi...</span>\r\n        </div>\r\n    </section>\r\n</div>\r\n<script>\r\nconst storefrontModel = {SerializeModel(model)};\r\n{BuildScript()}\r\n</script>\r\n</body>\r\n</html>";
	}

	private static object CreateSpotlightPayload(StoreGame game)
	{
		return new
		{
			id = game.GameId,
			title = game.Title,
			subtitle = (string.IsNullOrWhiteSpace(game.Subtitle) ? game.Category : game.Subtitle),
			metaText = game.BadgeText + " • " + game.Category,
			category = game.Category,
			badgeText = game.BadgeText,
			promoLabel = game.PromoLabel,
			originalPriceText = game.DisplayOriginalPriceText,
			salePriceText = game.DisplaySalePriceText,
			discountText = (string.IsNullOrWhiteSpace(game.DiscountText) ? "0%" : game.DiscountText),
			saleLimitText = game.SaleLimitText,
			purchaseText = game.PurchaseText,
			likes = game.Likes,
			dislikes = game.Dislikes,
			isFree = (game.SalePrice <= 0m),
			primaryColor = ToCssColor(game.PrimaryColor),
			secondaryColor = ToCssColor(game.SecondaryColor),
			imageUrl = SanitizeUrl((!string.IsNullOrWhiteSpace(game.SpotlightImageUrl)) ? game.SpotlightImageUrl : game.PosterImageUrl),
			thumbUrl = SanitizeUrl((!string.IsNullOrWhiteSpace(game.PosterImageUrl)) ? game.PosterImageUrl : game.SpotlightImageUrl)
		};
	}

	private static object CreateCatalogPayload(StoreGame game)
	{
		return new
		{
			id = game.GameId,
			title = game.Title,
			subtitle = (string.IsNullOrWhiteSpace(game.Subtitle) ? game.Category : game.Subtitle),
			category = game.Category,
			badgeText = game.BadgeText,
			promoLabel = game.PromoLabel,
			originalPriceText = game.DisplayOriginalPriceText,
			salePriceText = game.DisplaySalePriceText,
			discountText = game.DiscountText,
			saleLimitText = game.SaleLimitText,
			purchaseText = game.PurchaseText,
			likes = game.Likes,
			dislikes = game.Dislikes,
			isFree = (game.SalePrice <= 0m),
			primaryColor = ToCssColor(game.PrimaryColor),
			secondaryColor = ToCssColor(game.SecondaryColor),
			imageUrl = SanitizeUrl((!string.IsNullOrWhiteSpace(game.PosterImageUrl)) ? game.PosterImageUrl : game.SpotlightImageUrl)
		};
	}

	private static object CreateSalePayload(StoreSaleGame sale)
	{
		return new
		{
			id = sale.GameId,
			title = sale.Title,
			tag = sale.Tag,
			editionLabel = sale.EditionLabel,
			versionName = sale.VersionName,
			currentPriceText = sale.CurrentPriceText,
			referencePriceText = sale.ReferencePriceText,
			discountText = sale.DiscountText,
			saleName = sale.SaleName,
			saleEndsAtText = sale.SaleEndsAtText,
			primaryColor = ToCssColor(sale.PrimaryColor),
			secondaryColor = ToCssColor(sale.SecondaryColor),
			imageUrl = SanitizeUrl(sale.PosterImageUrl)
		};
	}

	private static object CreateCategorySectionPayload(StoreCategorySection section)
	{
		return new
		{
			name = section.Name,
			slug = section.Slug,
			games = section.Games.Select(CreateCatalogPayload).ToArray()
		};
	}

	private static string SerializeModel(object model)
	{
		return JsonSerializer.Serialize(model);
	}

	private static string? SanitizeUrl(string? value)
	{
		if (string.IsNullOrWhiteSpace(value))
		{
			return null;
		}
		string text = value.Trim();
		if (!Uri.TryCreate(text, UriKind.Absolute, out Uri _))
		{
			return null;
		}
		return text;
	}

	private static string ToCssColor(Color color)
	{
		return $"#{color.R:X2}{color.G:X2}{color.B:X2}";
	}

	private static string BuildStyles()
	{
