%, var(--hero-aura), transparent 38%),\r\n        radial-gradient(circle at 78% 28%, var(--hero-aura-soft), transparent 34%),\r\n        linear-gradient(180deg, color-mix(in srgb, var(--hero-aura-soft) 30%, transparent), transparent 70%);\r\n    pointer-events: none;\r\n    z-index: 0;\r\n}\r\n.hero-media-stage {\r\n    position: relative;\r\n    width: 100%;\r\n    height: 100%;\r\n    overflow: hidden;\r\n}\r\n.hero-media-image,\r\n.hero-media-slide { overflow: hidden; }\r\n\r\n.hero-card {\r\n    position: relative;\r\n    z-index: 1;\r\n    border: 1px solid var(--hero-line);\r\n    border-radius: 24px;\r\n    padding: 10px;\r\n    min-height: 352px;\r\n    height: 352px;\r\n    background:\r\n        linear-gradient(180deg, color-mix(in srgb, var(--hero-shell) 92%, rgba(13, 18, 25, 0.92)), color-mix(in srgb, var(--hero-shell-2) 90%, rgba(13, 18, 25, 0.96)));\r\n    box-shadow: var(--shadow);\r\n    transition: background 260ms ease, border-color 260ms ease;\r\n}\r\n.hero-grid {\r\n    display: grid;\r\n    grid-template-columns: minmax(0, 1.45fr) minmax(390px, 0.92fr);\r\n    gap: 14px;\r\n    align-items: stretch;\r\n    height: 100%;\r\n}\r\n.hero-media {\r\n    min-width: 0;\r\n    min-height: 0;\r\n    height: 100%;\r\n    overflow: hidden;\r\n    border-radius: 16px;\r\n    background: #1d150d;\r\n    cursor: pointer;\r\n}\r\n.hero-media-image,\r\n.hero-media-image img,\r\n.hero-media-slide,\r\n.hero-media-slide img,\r\n.spotlight-thumb,\r\n.spotlight-thumb img,\r\n.card-media-image,\r\n.card-media-image img {\r\n    width: 100%;\r\n    height: 100%;\r\n}\r\n.hero-media img,\r\n.spotlight-thumb img,\r\n.card-media-image img {\r\n    object-fit: cover;\r\n}\r\n.hero-media-slide {\r\n    position: absolute;\r\n    inset: 0;\r\n    z-index: 1;\r\n    opacity: 1;\r\n    transform: translate3d(0, 0, 0);\r\n}\r\n.hero-media-slide.is-next {\r\n    z-index: 2;\r\n    opacity: 0;\r\n    transform: translate3d(-8%, 0, 0);\r\n}\r\n.hero-media-slide.is-entering {\r\n    opacity: 1;\r\n    transform: translate3d(0, 0, 0);\r\n    transition: transform 560ms cubic-bezier(0.22, 1, 0.36, 1), opacity 560ms ease;\r\n}\r\n.hero-media-slide.is-leaving {\r\n    opacity: 0.18;\r\n    transform: translate3d(8%, 0, 0);\r\n    transition: transform 560ms cubic-bezier(0.22, 1, 0.36, 1), opacity 560ms ease;\r\n}\r\n.hero-media-slide img {\r\n    width: 104%;\r\n    height: 104%;\r\n    transform: translate3d(2%, 0, 0) scale(1.02);\r\n    transform-origin: center center;\r\n    will-change: transform;\r\n    backface-visibility: hidden;\r\n    animation: hero-pan 18s ease-in-out infinite alternate;\r\n}\r\n.hero-summary { min-width: 0; }\r\n.hero-summary-card {\r\n    height: 100%;\r\n    min-height: 0;\r\n    display: grid;\r\n    align-content: start;\r\n    gap: 0;\r\n    padding: 14px 18px 16px;\r\n    border-radius: 18px;\r\n    background: var(--hero-panel);\r\n    border: 1px solid var(--hero-panel-border);\r\n    cursor: pointer;\r\n    overflow: hidden;\r\n    transition: background-color 260ms ease, border-color 260ms ease;\r\n}\r\n.catalog-header,\r\n.card-price-row,\r\n.card-footer {\r\n    display: flex;\r\n    align-items: flex-start;\r\n    justify-content: space-between;\r\n    gap: 14px;\r\n}\r\n.discount-chip {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    min-height: 34px;\r\n    padding: 0 14px;\r\n    border-radius: 10px;\r\n    font-size: 0.8rem;\r\n    font-weight: 800;\r\n    letter-spacing: 0.04em;\r\n    text-transform: uppercase;\r\n}\r\n.hero-title {\r\n    margin: 0;\r\n    display: -webkit-box;\r\n    overflow: hidden;\r\n    -webkit-box-orient: vertical;\r\n    -webkit-line-clamp: 3;\r\n    font-size: clamp(1.45rem, 1.6vw, 1.95rem);\r\n    line-height: 1.15;\r\n    letter-spacing: 0;\r\n    overflow-wrap: break-word;\r\n}\r\n.hero-subtitle {\r\n    margin: 12px 0 14px;\r\n    color: #b8bba8;\r\n    font-size: 0.9rem;\r\n    line-height: 1.5;\r\n}\r\n.hero-facts { display: grid; gap: 10px; }\r\n.hero-fact {\r\n    display: grid;\r\n    grid-template-columns: minmax(0, 1fr) auto;\r\n    align-items: end;\r\n    gap: 12px;\r\n}\r\n.hero-fact-label { color: #b1b3a5; font-size: 0.9rem; }\r\n.hero-fact-value {\r\n    color: #f8f7f2;\r\n    font-size: 0.92rem;\r\n    font-weight: 600;\r\n    text-align: right;\r\n}\r\n.hero-fact-value.is-accent { color: var(--accent); font-size: 0.98rem; font-weight: 800; }\r\n.hero-fact-value.is-success,\r\n.discount-chip { color: var(--success); }\r\n.catalog-card {\r\n    border: 1px solid var(--line);\r\n    border-radius: 22px;\r\n    background: linear-gradient(180deg, var(--surface), var(--surface-2));\r\n    box-shadow: var(--shadow);\r\n}\r\n.hero-nav,\r\n.hero-nav-actions,\r\n.card-prices,\r\n.card-reactions {\r\n    display: flex;\r\n    align-items: center;\r\n    gap: 10px;\r\n}\r\n.hero-nav { justify-content: space-between; margin-bottom: 12px; }\r\n.hero-nav-title {\r\n    margin: 0;\r\n    color: var(--muted);\r\n    font-size: 0.82rem;\r\n    font-weight: 800;\r\n    letter-spacing: 0.10em;\r\n    text-transform: uppercase;\r\n}\r\n.nav-button,\r\n.spotlight-item,\r\n.catalog-card {\r\n    transition: transform 0.18s ease, background-color 0.18s ease, border-color 0.18s ease;\r\n}\r\n.nav-button:hover,\r\n.spotlight-item:hover,\r\n.catalog-card:hover { transform: translateY(-1px); }\r\n.nav-button,\r\n.spotlight-item {\r\n    border: 1px solid rgba(255, 255, 255, 0.08);\r\n    background: rgba(255, 255, 255, 0.04);\r\n    color: var(--text);\r\n    cursor: pointer;\r\n}\r\n.nav-button {\r\n    width: 38px;\r\n    height: 38px;\r\n    border-radius: 12px;\r\n}\r\n.spotlight-item-title,\r\n.card-title {\r\n    margin: 0;\r\n    font-weight: 700;\r\n    line-height: 1.42;\r\n}\r\n.spotlight-item-price strong,\r\n.card-prices strong { color: var(--accent); }\r\n.spotlight-item-price s,\r\n.card-prices s { color: var(--muted); }\r\n\r\n.catalog-header { align-items: end; margin-bottom: 18px; }\r\n.catalog-title {\r\n    margin: 0;\r\n    font-size: clamp(2rem, 2.7vw, 2.6rem);\r\n    line-height: 1.08;\r\n    letter-spacing: 0;\r\n}\r\n.catalog-counter,\r\n.card-subtitle,\r\n.sale-meta,\r\n.card-footer,\r\n.catalog-empty p { color: var(--text-soft); }\r\n.sale-shell,\r\n.catalog-shell {\r\n    display: grid;\r\n    gap: 16px;\r\n}\r\n.sale-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(4, minmax(0, 1fr));\r\n    gap: 14px;\r\n}\r\n.sale-card {\r\n    min-width: 0;\r\n    overflow: hidden;\r\n    border: 1px solid rgba(103, 231, 173, 0.24);\r\n    border-radius: 17px;\r\n    background: linear-gradient(180deg, rgba(21, 31, 42, 0.98), rgba(14, 20, 30, 0.98));\r\n    box-shadow: var(--shadow);\r\n    cursor: pointer;\r\n    transition: transform 0.18s ease, border-color 0.18s ease;\r\n}\r\n.sale-card:hover {\r\n    transform: translateY(-1px);\r\n    border-color: rgba(103, 231, 173, 0.44);\r\n}\r\n.sale-media {\r\n    position: relative;\r\n    aspect-ratio: 2.15;\r\n    overflow: hidden;\r\n    background: rgba(255, 255, 255, 0.04);\r\n}\r\n.sale-media img {\r\n    width: 100%;\r\n    height: 100%;\r\n    object-fit: cover;\r\n}\r\n.sale-body {\r\n    display: grid;\r\n    gap: 6px;\r\n    padding: 10px 12px 11px;\r\n}\r\n.sale-tag {\r\n    width: fit-content;\r\n    max-width: 100%;\r\n    padding: 4px 8px;\r\n    border-radius: 999px;\r\n    background: rgba(95, 140, 255, 0.13);\r\n    color: var(--accent);\r\n    font-size: 0.66rem;\r\n    font-weight: 800;\r\n    text-transform: uppercase;\r\n}\r\n.sale-title {\r\n    margin: 0;\r\n    display: -webkit-box;\r\n    overflow: hidden;\r\n    -webkit-box-orient: vertical;\r\n    -webkit-line-clamp: 2;\r\n    font-size: 0.9rem;\r\n    line-height: 1.28;\r\n}\r\n.sale-price-row {\r\n    display: flex;\r\n    flex-wrap: wrap;\r\n    align-items: baseline;\r\n    gap: 7px;\r\n}\r\n.sale-price-row strong {\r\n    color: var(--success);\r\n    font-size: 1rem;\r\n}\r\n.sale-price-row s {\r\n    color: var(--muted);\r\n    font-size: 0.86rem;\r\n}\r\n.sale-meta {\r\n    font-size: 0.78rem;\r\n    line-height: 1.25;\r\n}\r\n.catalog-sections {\r\n    display: grid;\r\n    gap: 30px;\r\n}\r\n.catalog-section {\r\n    display: grid;\r\n    gap: 14px;\r\n}\r\n.catalog-section-heading {\r\n    display: flex;\r\n    align-items: baseline;\r\n    justify-content: space-between;\r\n    gap: 14px;\r\n}\r\n.catalog-section-title {\r\n    margin: 0;\r\n    font-size: clamp(1.25rem, 1.6vw, 1.75rem);\r\n    letter-spacing: 0;\r\n}\r\n.catalog-section-count {\r\n    color: var(--muted);\r\n    font-size: 0.92rem;\r\n}\r\n.catalog-grid {\r\n    display: grid;\r\n    grid-template-columns: repeat(3, minmax(0, 1fr));\r\n    justify-content: stretch;\r\n    align-items: start;\r\n    gap: 16px;\r\n    width: 100%;\r\n}\r\n.catalog-card { overflow: hidden; cursor: pointer; }\r\n.card-media { position: relative; aspect-ratio: 1.7; overflow: hidden; background: rgba(255, 255, 255, 0.04); }\r\n.card-body { padding: 14px 14px 12px; display: grid; gap: 10px; }\r\n.card-title {\r\n    display: -webkit-box;\r\n    overflow: hidden;\r\n    -webkit-box-orient: vertical;\r\n    -webkit-line-clamp: 2;\r\n    font-size: 1rem;\r\n}\r\n.card-subtitle,\r\n.catalog-empty p { line-height: 1.6; }\r\n.card-prices { align-items: baseline; flex-wrap: wrap; }\r\n.card-prices strong { font-size: 1.1rem; }\r\n.card-prices s { font-size: 0.92rem; }\r\n.card-badge {\r\n    position: absolute;\r\n    left: 12px;\r\n    top: 12px;\r\n    max-width: calc(100% - 24px);\r\n    padding: 5px 9px;\r\n    border-radius: 999px;\r\n    background: rgba(8, 12, 18, 0.72);\r\n    border: 1px solid rgba(255, 255, 255, 0.14);\r\n    color: #fff;\r\n    font-size: 0.72rem;\r\n    font-weight: 800;\r\n    text-transform: uppercase;\r\n    white-space: nowrap;\r\n    overflow: hidden;\r\n    text-overflow: ellipsis;\r\n}\r\n.discount-chip { background: rgba(103, 231, 173, 0.12); }\r\n.card-reactions { flex-wrap: wrap; }\r\n.card-footer { font-size: 0.9rem; }\r\n\r\n.catalog-empty {\r\n    min-height: 240px;\r\n    display: grid;\r\n    place-items: center;\r\n    padding: 28px;\r\n    border-radius: 22px;\r\n    border: 1px dashed rgba(120, 149, 187, 0.34);\r\n    background: rgba(18, 25, 36, 0.6);\r\n    text-align: center;\r\n}\r\n.catalog-empty-icon {\r\n    display: inline-grid;\r\n    place-items: center;\r\n    width: 58px;\r\n    height: 58px;\r\n    margin: 0 auto 14px;\r\n    border-radius: 18px;\r\n    background: rgba(95, 140, 255, 0.14);\r\n    color: var(--accent);\r\n    font-size: 1.5rem;\r\n}\r\n.catalog-empty h3 { margin: 0 0 10px; font-size: 1.3rem; }\r\n.catalog-loader {\r\n    min-height: 86px;\r\n    display: flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    gap: 12px;\r\n    margin-top: 22px;\r\n    color: var(--text-soft);\r\n    font-weight: 700;\r\n}\r\n.catalog-loader-spinner {\r\n    width: 24px;\r\n    height: 24px;\r\n    border-radius: 999px;\r\n    border: 3px solid rgba(181, 192, 207, 0.24);\r\n    border-top-color: var(--accent);\r\n    animation: loader-spin 0.86s linear infinite;\r\n}\r\n\r\n.media-fallback {\r\n    width: 100%;\r\n    height: 100%;\r\n    display: grid;\r\n    place-items: center;\r\n    padding: 24px;\r\n    text-align: center;\r\n    background: linear-gradient(135deg, var(--fallback-primary), var(--fallback-secondary));\r\n}\r\n.media-fallback span {\r\n    display: inline-flex;\r\n    align-items: center;\r\n    justify-content: center;\r\n    padding: 14px 18px;\r\n    border-radius: 999px;\r\n    background: rgba(7, 11, 18, 0.34);\r\n    border: 1px solid rgba(255, 255, 255, 0.12);\r\n    font-size: clamp(1rem, 2.2vw, 1.8rem);\r\n    font-weight: 800;\r\n    letter-spacing: 0.06em;\r\n    text-transform: uppercase;\r\n}\r\n\r\n@keyframes hero-pan {\r\n    from {\r\n        transform: translate3d(2.2%, 0, 0) scale(1.02);\r\n    }\r\n    to {\r\n        transform: translate3d(-2.2%, 0, 0) scale(1.02);\r\n    }\r\n}\r\n\r\n@media (max-width: 1180px) {\r\n    .spotlight-host { width: 100%; }\r\n    .sale-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }\r\n    .hero-card {\r\n        height: 312px;\r\n        min-height: 312px;\r\n        padding: 9px;\r\n    }\r\n    .hero-grid {\r\n        grid-template-columns: minmax(0, 1.5fr) minmax(300px, 0.9fr);\r\n        gap: 10px;\r\n    }\r\n    .hero-media {\r\n        min-height: 0;\r\n        height: 100%;\r\n    }\r\n    .hero-summary-card {\r\n        height: 100%;\r\n        padding: 12px 14px 14px;\r\n    }\r\n    .hero-title {\r\n        font-size: 1.55rem;\r\n        -webkit-line-clamp: 2;\r\n    }\r\n    .hero-subtitle {\r\n        margin: 8px 0 10px;\r\n        font-size: 0.82rem;\r\n        line-height: 1.35;\r\n    }\r\n    .hero-facts { gap: 7px; }\r\n    .hero-fact-label { font-size: 0.82rem; }\r\n    .hero-fact-value { font-size: 0.84rem; }\r\n    .hero-fact-value.is-accent { font-size: 0.9rem; }\r\n}\r\n\r\n@media (max-width: 960px) {\r\n    .hero-card {\r\n        height: 276px;\r\n        min-height: 276px;\r\n    }\r\n    .hero-grid {\r\n        grid-template-columns: minmax(0, 1.55fr) minmax(254px, 0.82fr);\r\n        gap: 9px;\r\n    }\r\n    .hero-summary-card {\r\n        padding: 10px 12px 12px;\r\n    }\r\n    .hero-title { font-size: 1.32rem; }\r\n    .hero-subtitle {\r\n        margin: 6px 0 8px;\r\n        font-size: 0.76rem;\r\n    }\r\n    .hero-facts { gap: 6px; }\r\n    .hero-fact { gap: 8px; }\r\n    .hero-fact-label,\r\n    .hero-fact-value { font-size: 0.76rem; }\r\n    .hero-fact-value.is-accent { font-size: 0.82rem; }\r\n}\r\n\r\n@media (max-width: 860px) {\r\n    body { padding: 14px 12px 20px; }\r\n    .spotlight-host { padding: 10px; }\r\n    .hero-card {\r\n        height: 244px;\r\n        min-height: 244px;\r\n        padding: 8px;\r\n        border-radius: 20px;\r\n    }\r\n    .hero-grid {\r\n        grid-template-columns: minmax(0, 1.52fr) minmax(220px, 0.78fr);\r\n        gap: 8px;\r\n    }\r\n    .hero-media,\r\n    .hero-summary-card { border-radius: 14px; }\r\n    .hero-summary-card { padding: 9px 10px 10px; }\r\n    .hero-title {\r\n        font-size: 1.12rem;\r\n        line-height: 1.1;\r\n    }\r\n    .hero-subtitle {\r\n        margin: 5px 0 7px;\r\n        font-size: 0.7rem;\r\n        line-height: 1.3;\r\n    }\r\n    .hero-facts { gap: 5px; }\r\n    .hero-fact-label,\r\n    .hero-fact-value { font-size: 0.7rem; }\r\n    .hero-fact-value.is-accent { font-size: 0.76rem; }\r\n    .sale-grid,\r\n    .catalog-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\r\n}\r\n\r\n@keyframes loader-spin {\r\n    to {\r\n        transform: rotate(360deg);\r\n    }\r\n}\r\n\r\n@media (max-width: 560px) {\r\n    body { padding: 10px 8px 18px; }\r\n    .spotlight-host { padding: 6px; }\r\n    .hero-card {\r\n        height: 202px;\r\n        min-height: 202px;\r\n        padding: 6px;\r\n        border-radius: 16px;\r\n    }\r\n    .hero-grid {\r\n        grid-template-columns: minmax(0, 1.44fr) minmax(150px, 0.7fr);\r\n        gap: 6px;\r\n    }\r\n    .hero-media,\r\n    .hero-summary-card { border-radius: 11px; }\r\n    .hero-summary-card { padding: 7px 8px; }\r\n    .hero-title {\r\n        font-size: 0.94rem;\r\n        line-height: 1.08;\r\n    }\r\n    .hero-subtitle {\r\n        margin: 4px 0 5px;\r\n        font-size: 0.64rem;\r\n        line-height: 1.22;\r\n        white-space: nowrap;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n    }\r\n    .hero-facts { gap: 3px; }\r\n    .hero-fact { gap: 5px; }\r\n    .hero-fact-label,\r\n    .hero-fact-value {\r\n        min-width: 0;\r\n        font-size: 0.62rem;\r\n        white-space: nowrap;\r\n        overflow: hidden;\r\n        text-overflow: ellipsis;\r\n    }\r\n    .hero-fact-value.is-accent { font-size: 0.66rem; }\r\n    .sale-grid,\r\n    .catalog-grid { grid-template-columns: 1fr; }\r\n    .catalog-header,\r\n    .catalog-section-heading,\r\n    .card-price-row,\r\n    .card-footer {\r\n        flex-direction: column;\r\n        align-items: stretch;\r\n    }\r\n}\r\n\r\n@media (prefers-reduced-motion: reduce) {\r\n    .hero-media-slide,\r\n    .hero-media-slide.is-next,\r\n    .hero-media-slide.is-entering,\r\n    .hero-media-slide.is-leaving {\r\n        transition: none;\r\n        transform: translate3d(0, 0, 0);\r\n        opacity: 1;\r\n    }\r\n    .hero-media-slide img {\r\n        animation: none;\r\n        transform: scale(1.01);\r\n    }\r\n}";
