	private static string BuildScript()
	{
		return "(() => {\r\n    const model = storefrontModel ?? { spotlightGames: [], categorySections: [], saleGames: [], games: [], activeSpotlightIndex: 0 };\r\n    const root = document.documentElement;\r\n    const spotlightHost = document.querySelector('[data-spotlight-host]');\r\n    const saleShell = document.querySelector('[data-sale-shell]');\r\n    const saleGrid = document.querySelector('[data-sale-grid]');\r\n    const catalogSectionsHost = document.querySelector('[data-catalog-sections]');\r\n    const emptyState = document.querySelector('[data-empty-state]');\r\n    const catalogCounter = document.querySelector('[data-catalog-counter]');\r\n    const catalogLoader = document.querySelector('[data-catalog-loader]');\r\n    const catalogLoaderText = document.querySelector('[data-catalog-loader-text]');\r\n    const state = {\r\n        index: normalizeIndex(model.activeSpotlightIndex, model.spotlightGames?.length ?? 0),\r\n        timer: 0,\r\n        isReady: false,\r\n        isAnimating: false,\r\n        pendingIndex: null,\r\n        transitionHandle: 0,\r\n        catalogBatchSize: Math.max(1, Number.isFinite(model.catalogBatchSize) ? model.catalogBatchSize : 12),\r\n        catalogVisibleCount: 0,\r\n        catalogIsLoading: false,\r\n        catalogObserver: null\r\n    };\r\n\r\n    function normalizeIndex(index, length) {\r\n        if (!length) return 0;\r\n        const value = Number.isFinite(index) ? index : 0;\r\n        return ((value % length) + length) % length;\r\n    }\r\n\r\n    function escapeHtml(value) {\r\n        return String(value ?? '').replace(/[&<>\\\"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[character]));\r\n    }\r\n\r\n    function escapeCssIdentifier(value) {\r\n        const text = String(value ?? '');\r\n        return window.CSS?.escape ? window.CSS.escape(text) : text.replace(/[\"\\\\]/g, '\\\\$&');\r\n    }\r\n\r\n    function safeUrl(value) {\r\n        if (typeof value !== 'string' || value.trim().length === 0) return '';\r\n        const trimmed = value.trim();\r\n        return /^https?:\\/\\//i.test(trimmed) || /^data:image\\//i.test(trimmed) ? trimmed : '';\r\n    }\r\n\r\n    function fallbackMarkup(game, className) {\r\n        const title = escapeHtml((game?.title ?? 'Store').split(' ').slice(0, 3).join(' '));\r\n        const primary = escapeHtml(game?.primaryColor ?? '#35507d');\r\n        const secondary = escapeHtml(game?.secondaryColor ?? '#172332');\r\n        return `<div class=\"${className} media-fallback\" style=\"--fallback-primary:${primary};--fallback-secondary:${secondary};\"><span>${title}</span></div>`;\r\n    }\r\n\r\n    function renderImage(url, alt, className, game) {\r\n        const safe = safeUrl(url);\r\n        return safe\r\n            ? `<div class=\"${className}\"><img src=\"${safe}\" alt=\"${escapeHtml(alt)}\" loading=\"lazy\" /></div>`\r\n            : fallbackMarkup(game, className);\r\n    }\r\n\r\n    function getSpotlightGames() {\r\n        return Array.isArray(model.spotlightGames) ? model.spotlightGames : [];\r\n    }\r\n\r\n    function getCatalogGames() {\r\n        return Array.isArray(model.games) ? model.games : [];\r\n    }\r\n\r\n    function getSaleGames() {\r\n        return Array.isArray(model.saleGames) ? model.saleGames : [];\r\n    }\r\n\r\n    function getCategorySections() {\r\n        if (Array.isArray(model.categorySections) && model.categorySections.length) {\r\n            return model.categorySections;\r\n        }\r\n\r\n        const games = getCatalogGames();\r\n        return games.length ? [{ name: 'Tất cả game', slug: 'tat-ca-game', games }] : [];\r\n    }\r\n\r\n    function getCatalogEntries() {\r\n        return getCategorySections().flatMap((section, sectionIndex) => {\r\n            const games = Array.isArray(section.games) ? section.games : [];\r\n            const slug = String(section.slug || `section-${sectionIndex}`);\r\n            return games.map((game, gameIndex) => ({\r\n                section: {\r\n                    name: section.name || 'Game',\r\n                    slug,\r\n                    index: sectionIndex,\r\n                    total: games.length\r\n                },\r\n                game,\r\n                key: `${slug}:${game.id || gameIndex}:${gameIndex}`\r\n            }));\r\n        });\r\n    }\r\n\r\n    function parseHexColor(value, fallback) {\r\n        const source = typeof value === 'string' && /^#?[0-9a-f]{6}$/i.test(value.trim())\r\n            ? value.trim().replace('#', '')\r\n            : fallback.replace('#', '');\r\n        return {\r\n            r: Number.parseInt(source.slice(0, 2), 16),\r\n            g: Number.parseInt(source.slice(2, 4), 16),\r\n            b: Number.parseInt(source.slice(4, 6), 16)\r\n        };\r\n    }\r\n\r\n    function clampChannel(value) {\r\n        return Math.max(0, Math.min(255, Math.round(value)));\r\n    }\r\n\r\n    function colorToHex(color) {\r\n        return `#${[color.r, color.g, color.b].map(channel => clampChannel(channel).toString(16).padStart(2, '0')).join('')}`;\r\n    }\r\n\r\n    function mixColors(first, second, weight, firstFallback = '#35507d', secondFallback = '#172332') {\r\n        const a = parseHexColor(first, firstFallback);\r\n        const b = parseHexColor(second, secondFallback);\r\n        const ratio = Math.max(0, Math.min(1, weight));\r\n        return colorToHex({\r\n            r: a.r + ((b.r - a.r) * ratio),\r\n            g: a.g + ((b.g - a.g) * ratio),\r\n            b: a.b + ((b.b - a.b) * ratio)\r\n        });\r\n    }\r\n\r\n    function colorWithAlpha(value, alpha, fallback = '#35507d') {\r\n        const color = parseHexColor(value, fallback);\r\n        const opacity = Math.max(0, Math.min(1, alpha));\r\n        return `rgba(${clampChannel(color.r)}, ${clampChannel(color.g)}, ${clampChannel(color.b)}, ${opacity})`;\r\n    }\r\n\r\n    function applySpotlightTheme(game) {\r\n        const primary = game?.primaryColor ?? '#35507d';\r\n        const secondary = game?.secondaryColor ?? '#172332';\r\n        const heroShell = mixColors(primary, '#18212c', 0.84, '#35507d', '#18212c');\r\n        const heroShellDark = mixColors(secondary, '#121821', 0.86, '#172332', '#121821');\r\n        const heroLine = colorWithAlpha(mixColors(primary, '#93a5bd', 0.72, '#35507d', '#93a5bd'), 0.22, '#93a5bd');\r\n        const heroAura = colorWithAlpha(mixColors(primary, secondary, 0.34, '#35507d', '#172332'), 0.09, '#35507d');\r\n        const heroAuraSoft = colorWithAlpha(mixColors(primary, '#0d1219', 0.62, '#35507d', '#0d1219'), 0.035, '#35507d');\r\n\r\n        root.style.setProperty('--hero-shell', heroShell);\r\n        root.style.setProperty('--hero-shell-2', heroShellDark);\r\n        root.style.setProperty('--hero-line', heroLine);\r\n        root.style.setProperty('--hero-aura', heroAura);\r\n        root.style.setProperty('--hero-aura-soft', heroAuraSoft);\r\n    }\r\n\r\n    function postMessage(message) {\r\n        if (window.chrome?.webview?.postMessage) {\r\n            window.chrome.webview.postMessage(message);\r\n        }\r\n    }\r\n\r\n    function ensureSpotlightShell() {\r\n        if (state.isReady) {\r\n            return;\r\n        }\r\n\r\n        const games = getSpotlightGames();\r\n        if (!games.length) {\r\n            applySpotlightTheme(null);\r\n            spotlightHost.innerHTML = '<div class=\"hero-card\"><div class=\"catalog-empty\"><div><div class=\"catalog-empty-icon\">?</div><h3>Chưa có dữ liệu storefront</h3><p>Launcher đang chờ dữ liệu spotlight từ API.</p></div></div></div>';\r\n            return;\r\n        }\r\n\r\n        spotlightHost.innerHTML = `\r\n            <div class=\"hero-card\">\r\n                <div class=\"hero-grid\">\r\n                    <div class=\"hero-media\" data-open-game=\"\">\r\n                        <div class=\"hero-media-stage\" data-hero-media-stage></div>\r\n                    </div>\r\n                    <div class=\"hero-summary\">\r\n                        <div class=\"hero-summary-card\" data-open-game=\"\">\r\n                            <h1 class=\"hero-title\" data-hero-title></h1>\r\n                            <p class=\"hero-subtitle\" data-hero-subtitle></p>\r\n                            <div class=\"hero-facts\">\r\n                                <div class=\"hero-fact\">\r\n                                    <span class=\"hero-fact-label\">Giá gốc</span>\r\n                                    <strong class=\"hero-fact-value\" data-hero-original></strong>\r\n                                </div>\r\n                                <div class=\"hero-fact\">\r\n                                    <span class=\"hero-fact-label\">Giảm</span>\r\n                                    <strong class=\"hero-fact-value\" data-hero-discount></strong>\r\n                                </div>\r\n                                <div class=\"hero-fact\">\r\n                                    <span class=\"hero-fact-label\">Giá sau sale</span>\r\n                                    <strong class=\"hero-fact-value is-accent\" data-hero-sale></strong>\r\n                                </div>\r\n                                <div class=\"hero-fact\">\r\n                                    <span class=\"hero-fact-label\">Hạn sale</span>\r\n                                    <strong class=\"hero-fact-value\" data-hero-limit></strong>\r\n                                </div>\r\n                                <div class=\"hero-fact\">\r\n                                    <span class=\"hero-fact-label\">Thể loại</span>\r\n                                    <strong class=\"hero-fact-value\" data-hero-category></strong>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </div>`;\r\n\r\n        state.isReady = true;\r\n    }\r\n\r\n    function getSpotlightElements() {\r\n        return {\r\n            media: spotlightHost.querySelector('[data-open-game].hero-media, .hero-media[data-open-game]') ?? spotlightHost.querySelector('.hero-media'),\r\n            summary: spotlightHost.querySelector('.hero-summary-card'),\r\n            stage: spotlightHost.querySelector('[data-hero-media-stage]'),\r\n            title: spotlightHost.querySelector('[data-hero-title]'),\r\n            subtitle: spotlightHost.querySelector('[data-hero-subtitle]'),\r\n            original: spotlightHost.querySelector('[data-hero-original]'),\r\n            discount: spotlightHost.querySelector('[data-hero-discount]'),\r\n            sale: spotlightHost.querySelector('[data-hero-sale]'),\r\n            limit: spotlightHost.querySelector('[data-hero-limit]'),\r\n            category: spotlightHost.querySelector('[data-hero-category]')\r\n        };\r\n    }\r\n\r\n    function setOpenGameTargets(elements, game) {\r\n        elements.media?.setAttribute('data-open-game', game.id);\r\n        elements.summary?.setAttribute('data-open-game', game.id);\r\n    }\r\n\r\n    function updateSpotlightText(elements, game) {\r\n        if (elements.title) {\r\n            elements.title.textContent = game.title || '';\r\n            elements.title.title = game.title || '';\r\n        }\r\n        if (elements.subtitle) elements.subtitle.textContent = game.metaText || game.subtitle || '';\r\n        if (elements.original) elements.original.textContent = game.originalPriceText || '--';\r\n\r\n        if (elements.discount) {\r\n            elements.discount.textContent = game.discountText || '0%';\r\n            elements.discount.classList.toggle('is-success', Boolean(game.discountText && game.discountText !== '0%'));\r\n        }\r\n\r\n        if (elements.sale) elements.sale.textContent = game.salePriceText || '--';\r\n        if (elements.limit) elements.limit.textContent = game.saleLimitText || 'Không giới hạn';\r\n        if (elements.category) elements.category.textContent = game.category || '--';\r\n    }\r\n\r\n    function buildHeroSlide(game, extraClass = 'is-current') {\r\n        return renderImage(game.imageUrl, game.title, `hero-media-image hero-media-slide ${extraClass}`.trim(), game);\r\n    }\r\n\r\n    function completePendingTransition() {\r\n        if (state.transitionHandle) {\r\n            window.clearTimeout(state.transitionHandle);\r\n            state.transitionHandle = 0;\r\n        }\r\n\r\n        state.isAnimating = false;\r\n        if (state.pendingIndex === null) {\r\n            return;\r\n        }\r\n\r\n        const nextIndex = state.pendingIndex;\r\n        state.pendingIndex = null;\r\n        void setSpotlightIndex(nextIndex, true);\r\n    }\r\n\r\n    function transitionHeroImage(elements, game) {\r\n        const stage = elements.stage;\r\n        if (!stage) {\r\n            return;\r\n        }\r\n\r\n        const current = stage.querySelector('.hero-media-slide.is-current');\r\n        if (!current) {\r\n            stage.innerHTML = buildHeroSlide(game, 'is-current');\r\n            return;\r\n        }\r\n\r\n        const incomingMarkup = buildHeroSlide(game, 'is-next');\r\n        stage.insertAdjacentHTML('beforeend', incomingMarkup);\r\n        const incoming = stage.lastElementChild;\r\n        if (!(incoming instanceof HTMLElement)) {\r\n            stage.innerHTML = buildHeroSlide(game, 'is-current');\r\n            return;\r\n        }\r\n\r\n        state.isAnimating = true;\r\n        requestAnimationFrame(() => {\r\n            current.classList.add('is-leaving');\r\n            incoming.classList.add('is-entering');\r\n        });\r\n\r\n        state.transitionHandle = window.setTimeout(() => {\r\n            current.remove();\r\n            incoming.classList.remove('is-next', 'is-entering');\r\n            incoming.classList.add('is-current');\r\n            completePendingTransition();\r\n        }, 580);\r\n    }\r\n\r\n    function updateSpotlightView(game, animateImage) {\r\n        applySpotlightTheme(game);\r\n        ensureSpotlightShell();\r\n        if (!state.isReady) {\r\n            return;\r\n        }\r\n\r\n        const elements = getSpotlightElements();\r\n        setOpenGameTargets(elements, game);\r\n        updateSpotlightText(elements, game);\r\n\r\n        if (!elements.stage) {\r\n            return;\r\n        }\r\n\r\n        if (!animateImage || !elements.stage.children.length) {\r\n            elements.stage.innerHTML = buildHeroSlide(game, 'is-current');\r\n            return;\r\n        }\r\n\r\n        transitionHeroImage(elements, game);\r\n    }\r\n\r\n    function renderSaleSection() {\r\n        const sales = getSaleGames();\r\n        if (!saleShell || !saleGrid || !sales.length) {\r\n            if (saleShell) saleShell.hidden = true;\r\n            return;\r\n        }\r\n\r\n        saleShell.hidden = false;\r\n        saleGrid.innerHTML = sales.map(sale => `\r\n            <article class=\"sale-card\" data-open-game=\"${escapeHtml(sale.id)}\">\r\n                <div class=\"sale-media\">\r\n                    ${renderImage(sale.imageUrl, sale.title, 'card-media-image', sale)}\r\n                    ${sale.discountText ? `<span class=\"discount-chip card-badge\">${escapeHtml(sale.discountText)}</span>` : ''}\r\n                </div>\r\n                <div class=\"sale-body\">\r\n                    <span class=\"sale-tag\">${escapeHtml(sale.editionLabel || sale.tag || 'Sale')}</span>\r\n                    <h3 class=\"sale-title\">${escapeHtml(sale.title || '')}</h3>\r\n                    <div class=\"sale-price-row\">\r\n                        ${sale.referencePriceText ? `<s>${escapeHtml(sale.referencePriceText)}</s>` : ''}\r\n                        <strong>${escapeHtml(sale.currentPriceText || '--')}</strong>\r\n                    </div>\r\n                    <div class=\"sale-meta\">${escapeHtml(sale.saleEndsAtText || sale.saleName || sale.tag || '')}</div>\r\n                </div>\r\n            </article>`).join('');\r\n    }\r\n\r\n    function renderCatalogCard(game) {\r\n        return `\r\n            <article class=\"catalog-card\" data-open-game=\"${escapeHtml(game.id)}\">\r\n                <div class=\"card-media\">\r\n                    ${renderImage(game.imageUrl, game.title, 'card-media-image', game)}\r\n                    ${game.badgeText ? `<span class=\"card-badge\">${escapeHtml(game.badgeText)}</span>` : ''}\r\n                </div>\r\n                <div class=\"card-body\">\r\n                    <div>\r\n                        <h3 class=\"card-title\">${escapeHtml(game.title)}</h3>\r\n                        <div class=\"card-subtitle\">${escapeHtml(game.subtitle || game.category || '')}</div>\r\n                    </div>\r\n                    <div class=\"card-price-row\">\r\n                        <div class=\"card-prices\">\r\n                            <strong>${escapeHtml(game.salePriceText || '--')}</strong>\r\n                            ${game.originalPriceText && game.originalPriceText !== game.salePriceText ? `<s>${escapeHtml(game.originalPriceText)}</s>` : ''}\r\n                        </div>\r\n                        ${game.discountText ? `<span class=\"discount-chip\">${escapeHtml(game.discountText)}</span>` : ''}\r\n                    </div>\r\n                    <div class=\"card-footer\">\r\n                        <span>${escapeHtml(game.category || '')}</span>\r\n                        <div class=\"card-reactions\">\r\n                            <span>+ ${escapeHtml(game.likes)}</span>\r\n                            <span>- ${escapeHtml(game.dislikes)}</span>\r\n                            <span>${escapeHtml(game.purchaseText || '')}</span>\r\n                        </div>\r\n                    </div>\r\n                </div>\r\n            </article>`;\r\n    }\r\n\r\n    function sectionDomId(section) {\r\n        return `catalog-section-${String(section.slug || section.index || 'game').replace(/[^a-z0-9_-]/gi, '-')}`;\r\n    }\r\n\r\n    function ensureCatalogSection(section) {\r\n        const slug = String(section.slug || section.index || 'game');\r\n        let container = catalogSectionsHost.querySelector(`[data-catalog-section=\"${escapeCssIdentifier(slug)}\"]`);\r\n        if (container) {\r\n            return container;\r\n        }\r\n\r\n        const id = sectionDomId(section);\r\n        catalogSectionsHost.insertAdjacentHTML('beforeend', `\r\n            <section class=\"catalog-section\" data-catalog-section=\"${escapeHtml(slug)}\" aria-labelledby=\"${escapeHtml(id)}\">\r\n                <div class=\"catalog-section-heading\">\r\n                    <h3 class=\"catalog-section-title\" id=\"${escapeHtml(id)}\">${escapeHtml(section.name || 'Game')}</h3>\r\n                    <span class=\"catalog-section-count\">${escapeHtml(section.total || 0)} game</span>\r\n                </div>\r\n                <div class=\"catalog-grid\" data-section-grid></div>\r\n            </section>`);\r\n        return catalogSectionsHost.lastElementChild;\r\n    }\r\n\r\n    function renderCatalogEntries(entries, append) {\r\n        if (!append) {\r\n            catalogSectionsHost.innerHTML = '';\r\n        }\r\n\r\n        entries.forEach(entry => {\r\n            const sectionElement = ensureCatalogSection(entry.section);\r\n            const grid = sectionElement?.querySelector('[data-section-grid]');\r\n            if (grid) {\r\n                grid.insertAdjacentHTML('beforeend', renderCatalogCard(entry.game));\r\n            }\r\n        });\r\n    }\r\n\r\n    function renderCatalogToCount(targetCount) {\r\n        const entries = getCatalogEntries();\r\n        if (!entries.length) {\r\n            catalogSectionsHost.innerHTML = '';\r\n            state.catalogVisibleCount = 0;\r\n            state.catalogIsLoading = false;\r\n            emptyState.hidden = false;\r\n            updateCatalogCounter(0);\r\n            updateCatalogLoader();\r\n            return;\r\n        }\r\n\r\n        emptyState.hidden = true;\r\n        const requestedCount = Math.max(state.catalogBatchSize, Math.round(Number(targetCount) || 0));\r\n        state.catalogVisibleCount = Math.min(entries.length, requestedCount);\r\n        state.catalogIsLoading = false;\r\n        renderCatalogEntries(entries.slice(0, state.catalogVisibleCount), false);\r\n        updateCatalogCounter(entries.length);\r\n        updateCatalogLoader();\r\n        observeCatalogLoader();\r\n    }\r\n\r\n    function updateCatalogCounter(totalCount) {\r\n        if (totalCount === 0) {\r\n            catalogCounter.textContent = 'Không tìm thấy sản phẩm';\r\n            postMessage('catalog-count:0:0');\r\n            return;\r\n        }\r\n\r\n        catalogCounter.textContent = `Hiển thị ${state.catalogVisibleCount}/${totalCount} trò chơi`;\r\n        postMessage(`catalog-count:${state.catalogVisibleCount}:${totalCount}`);\r\n    }\r\n\r\n    function hasMoreCatalogGames() {\r\n        return state.catalogVisibleCount < getCatalogEntries().length;\r\n    }\r\n\r\n    function updateCatalogLoader() {\r\n        if (!catalogLoader) {\r\n            return;\r\n        }\r\n\r\n        const hasMore = hasMoreCatalogGames();\r\n        catalogLoader.hidden = !hasMore;\r\n        if (catalogLoaderText) {\r\n            catalogLoaderText.textContent = hasMore ? 'Đang tải thêm trò chơi...' : '';\r\n        }\r\n    }\r\n\r\n    function isNearCatalogBottom() {\r\n        const scrollElement = document.scrollingElement || document.documentElement;\r\n        return scrollElement.scrollHeight - (window.scrollY + window.innerHeight) < 520;\r\n    }\r\n\r\n    function loadMoreCatalogGames() {\r\n        const entries = getCatalogEntries();\r\n        if (state.catalogIsLoading || !hasMoreCatalogGames()) {\r\n            return;\r\n        }\r\n\r\n        state.catalogIsLoading = true;\r\n        updateCatalogLoader();\r\n\r\n        window.setTimeout(() => {\r\n            const nextVisibleCount = Math.min(entries.length, state.catalogVisibleCount + state.catalogBatchSize);\r\n            const nextEntries = entries.slice(state.catalogVisibleCount, nextVisibleCount);\r\n            renderCatalogEntries(nextEntries, true);\r\n            state.catalogVisibleCount = nextVisibleCount;\r\n            state.catalogIsLoading = false;\r\n            updateCatalogCounter(entries.length);\r\n            updateCatalogLoader();\r\n\r\n            if (hasMoreCatalogGames() && isNearCatalogBottom()) {\r\n                loadMoreCatalogGames();\r\n            }\r\n        }, 160);\r\n    }\r\n\r\n    function handleCatalogScroll() {\r\n        if (isNearCatalogBottom()) {\r\n            loadMoreCatalogGames();\r\n        }\r\n    }\r\n\r\n    function observeCatalogLoader() {\r\n        if (state.catalogObserver) {\r\n            state.catalogObserver.disconnect();\r\n            state.catalogObserver = null;\r\n        }\r\n\r\n        window.removeEventListener('scroll', handleCatalogScroll);\r\n        window.addEventListener('scroll', handleCatalogScroll, { passive: true });\r\n\r\n        if (!catalogLoader || !('IntersectionObserver' in window)) {\r\n            return;\r\n        }\r\n\r\n        state.catalogObserver = new IntersectionObserver(entries => {\r\n            if (entries.some(entry => entry.isIntersecting)) {\r\n                loadMoreCatalogGames();\r\n            }\r\n        }, { rootMargin: '520px 0px' });\r\n\r\n        state.catalogObserver.observe(catalogLoader);\r\n    }\r\n\r\n    function renderCatalog() {\r\n        renderCatalogToCount(state.catalogBatchSize);\r\n        window.setTimeout(handleCatalogScroll, 80);\r\n    }\r\n\r\n    function restoreStorefrontPosition(returnPosition) {\r\n        const targetScrollY = Math.max(0, Math.round(Number(returnPosition?.scrollY) || 0));\r\n        const minimumVisibleCount = Math.max(0, Math.round(Number(returnPosition?.catalogVisibleCount) || 0));\r\n        if (minimumVisibleCount > state.catalogVisibleCount) {\r\n            renderCatalogToCount(minimumVisibleCount);\r\n        }\r\n\r\n        window.requestAnimationFrame(() => {\r\n            window.requestAnimationFrame(() => {\r\n                const scrollElement = document.scrollingElement || document.documentElement;\r\n                const maxScrollY = Math.max(0, scrollElement.scrollHeight - window.innerHeight);\r\n                window.scrollTo({ left: 0, top: Math.min(targetScrollY, maxScrollY), behavior: 'auto' });\r\n            });\r\n        });\r\n    }\r\n\r\n    window.__nestgStorefront = {\r\n        getCatalogVisibleCount: () => state.catalogVisibleCount,\r\n        restorePosition: restoreStorefrontPosition\r\n    };\r\n\r\n    async function setSpotlightIndex(nextIndex, notifyHost) {\r\n        const games = getSpotlightGames();\r\n        if (!games.length) return;\r\n\r\n        const normalizedIndex = normalizeIndex(nextIndex, games.length);\r\n        if (state.isAnimating) {\r\n            state.pendingIndex = normalizedIndex;\r\n            if (notifyHost) postMessage(`spotlight:${normalizedIndex}`);\r\n            return;\r\n        }\r\n\r\n        const shouldAnimate = state.isReady && normalizedIndex !== state.index;\r\n        state.index = normalizedIndex;\r\n        updateSpotlightView(games[state.index], shouldAnimate);\r\n        if (notifyHost) postMessage(`spotlight:${state.index}`);\r\n    }\r\n\r\n    function restartAutoplay() {\r\n        if (state.timer) {\r\n            window.clearInterval(state.timer);\r\n            state.timer = 0;\r\n        }\r\n\r\n        const games = Array.isArray(model.spotlightGames) ? model.spotlightGames : [];\r\n        if (games.length <= 1) return;\r\n        state.timer = window.setInterval(() => setSpotlightIndex(state.index + 1, true), 3500);\r\n    }\r\n\r\n    document.addEventListener('click', event => {\r\n        const target = event.target instanceof Element ? event.target : null;\r\n        if (!target) return;\r\n\r\n        const spotlightTrigger = target.closest('[data-spotlight-index]');\r\n        if (spotlightTrigger) {\r\n            setSpotlightIndex(Number.parseInt(spotlightTrigger.getAttribute('data-spotlight-index') ?? '0', 10), true);\r\n            restartAutoplay();\r\n            return;\r\n        }\r\n\r\n        const navTrigger = target.closest('[data-nav]');\r\n        if (navTrigger) {\r\n            setSpotlightIndex(state.index + (navTrigger.getAttribute('data-nav') === 'prev' ? -1 : 1), true);\r\n            restartAutoplay();\r\n            return;\r\n        }\r\n\r\n        const openTrigger = target.closest('[data-open-game]');\r\n        const gameId = openTrigger?.getAttribute('data-open-game');\r\n        if (gameId) {\r\n            postMessage(`game:${gameId}`);\r\n        }\r\n    });\r\n\r\n    window.addEventListener('beforeunload', () => {\r\n        if (state.timer) window.clearInterval(state.timer);\r\n        if (state.transitionHandle) window.clearTimeout(state.transitionHandle);\r\n        if (state.catalogObserver) state.catalogObserver.disconnect();\r\n        window.removeEventListener('scroll', handleCatalogScroll);\r\n    });\r\n\r\n    const initialGames = getSpotlightGames();\r\n    if (initialGames.length) {\r\n        ensureSpotlightShell();\r\n        updateSpotlightView(initialGames[state.index], false);\r\n    } else {\r\n        ensureSpotlightShell();\r\n    }\r\n    renderSaleSection();\r\n    renderCatalog();\r\n    restartAutoplay();\r\n})();";
